// CO-GC-002 was generated by the dashboard and its File column said "—".
//
// fileCell read the Attachment only. The document the dashboard had just drawn
// lives in Signed File, so nothing on the row pointed at the one file somebody
// actually wants from it: the change order itself.
import fs from 'fs';
import { bootPage, SEED } from './tools-harness.mjs';
let n=0, bad=0;
const ok=(c,m)=>{ n++; if(!c){ bad++; console.error('  FAIL:',m); } };
const html = fs.readFileSync('index.html','utf8');
const P=bootPage(); P.run(SEED);
const cell=r=>P.run('fileCell('+JSON.stringify(r)+')');
// The file a link opens, in order of appearance.
const opens=h=>[...String(h).matchAll(/openBoxFile\('([^']*)'/g)].map(m=>m[1]);

console.log('The report');
{
  const h=cell({'CO #':'CO-GC-002','Company':'Summit Builders',
    'Signed File ID':'s1','Signed File Name':'Summit Builders — CO-GC-002.pdf'});
  ok(!/—<\/span>$/.test(h), 'a generated change order no longer shows an em dash');
  ok(opens(h).join()==='s1', 'it links the document that was drawn');
  ok(/CO-GC-002\.pdf/.test(h), 'by name');
  ok(/dl-btn/.test(h), 'and can be downloaded, like any other file on a row');
}

console.log('Both files, in the order somebody wants them');
{
  const h=cell({'PCO #':'PCO-GC-001','Attachment File ID':'a1','Attachment Name':'Screenshot.png',
                'Signed File ID':'s2','Signed File Name':'PCO-GC-001.pdf'});
  ok(opens(h).join()==='s2,a1', 'the generated document comes first, the attachment under it');
  ok(/Supporting:/.test(h), 'labelled, so the second one is not mistaken for the document');
  ok(/cell-sub/.test(h), 'as a sub-line rather than a second full row');
  ok((h.match(/dl-btn/g)||[]).length===2, 'both downloadable');
  ok(/Screenshot\.png/.test(h), 'the contractor’s own file is still reachable — it is what justifies the document');
}

console.log('What must not double up');
{
  // Uploading an executed change order records it as both attachment and signed.
  const h=cell({'CO #':'CO-GC-003','Attachment File ID':'u1','Attachment Name':'signed.pdf',
                'Signed File ID':'u1','Signed File Name':'signed.pdf'});
  ok(opens(h).join()==='u1', 'one file recorded twice is listed once');
  ok(!/Supporting:/.test(h), 'and not described as supporting itself');
}

console.log('Rows that have not changed');
{
  ok(opens(cell({'PCO #':'PCO-GC-001','Attachment File ID':'a1','Attachment Name':'Screenshot.png'})).join()==='a1',
     'an attachment with no generated document reads exactly as before');
  ok(/—/.test(cell({'PCO #':'PCO-GC-004'})), 'a row with no files at all still shows an em dash');
  ok(/—/.test(cell({})), 'and so does an empty row');
  // RFIs and submittals carry no Signed File column, so nothing about them moves.
  ok(opens(cell({'RFI #':'RFI-GC-001','Attachment File ID':'r1','Attachment Name':'sketch.pdf'})).join()==='r1',
     'an RFI is untouched');
  // The older File ID / File Name spelling still works.
  ok(opens(cell({'File ID':'f1','File Name':'old.pdf'})).join()==='f1', 'and so is the older column spelling');
}

console.log('Wiring');
{
  const f=html.slice(html.indexOf('function fileCell(r){'));
  const body=f.slice(0, f.indexOf('\n}')+2);
  ok(/r\['Signed File ID'\]/.test(body), 'the cell reads the signed document');
  ok(/String\(sfid\)===String\(afid\)/.test(body), 'and compares the two as strings, since a CSV has no numbers');
}
ok((html.match(/function fileLink\(/g)||[]).length===1,
   'the link markup is written once and used for both, so they cannot drift apart');

console.log((bad?'FAIL':'ok  ')+' tools-test-filecell.mjs — '+n+' assertions'+(bad?', '+bad+' failed':''));
process.exit(bad?1:0);
